func levenshtein(a, b string) int {
	la := len(a)
	lb := len(b)
	dp := make([][]int, la+1)
	for i := range dp {
		dp[i] = make([]int, lb+1)
	}
	for i := 0; i <= la; i++ {
		dp[i][0] = i
	}
	for j := 0; j <= lb; j++ {
		dp[0][j] = j
	}
	for i := 1; i <= la; i++ {
		for j := 1; j <= lb; j++ {
			cost := 0
			if a[i-1] != b[j-1] {
				cost = 1
			}
			dp[i][j] = min(dp[i-1][j]+1, min(dp[i][j-1]+1, dp[i-1][j-1]+cost))
		}
	}
	return dp[la][lb]
}
func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func suggestCommand(input string) string {
	// strip leading dashes for comparison
	trimmed := strings.TrimLeft(input, "-")
	candidates := []string{"check", "doc", "help", "version"}
	best := ""
	bestDist := 100
	for _, c := range candidates {
		// if trimmed == c exactly, suggest
		if trimmed == c {
			return c
		}
		// compute distance between input and candidate and also trimmed and candidate
		d1 := levenshtein(input, c)
		d2 := levenshtein(trimmed, c)
		d := d1
		if d2 < d {
			d = d2
		}
		// also check if input contains candidate?
		if d <= 2 && d < bestDist {
			bestDist = d
			best = c
		}
	}
	// also check for --help etc: if trimmed == "help" etc already handled
	// For "--help" -> trimmed "help" -> exact match, returns help
	return best
}

func handleUnknownCommand(cmd string) {
	suggest := suggestCommand(cmd)
	if suggest != "" {
		fmt.Fprintf(os.Stdout, "\"%s\" unknown command, did you mean \"%s\"?\nRun \"go-critic help\" for usage.\n\n", cmd, suggest)
	} else {
		fmt.Fprintf(os.Stdout, "\"%s\" unknown command\nRun \"go-critic help\" for usage.\n\n", cmd)
	}
	fmt.Fprintf(os.Stderr, "no such command \"%s\"\n", cmd)
	os.Exit(0)
}

func printHelp() {
	fmt.Fprint(os.Stdout, helpText)
}

func main() {
	if len(os.Args) < 2 {
		fmt.Fprint(os.Stderr, "no args provided\n")
		os.Exit(0)
	}
	cmd := os.Args[1]
	switch cmd {
	case "help":
		// help command ignores extra args and prints help
		printHelp()
		os.Exit(0)
	case "version":
		// version command: should print version even with extra args? Original prints version even with extra args? We saw version extra prints version and exit 0
		fmt.Fprint(os.Stdout, versionText)
		os.Exit(0)
	case "doc":
		runDoc(os.Args[2:])
	case "check":
		runCheck(os.Args[2:])
	default:
		// unknown command handling
		handleUnknownCommand(cmd)
	}
}

