	var buf bytes.Buffer
	fs.SetOutput(&buf) // we will capture and then output to stderr ourselves? Actually original outputs to stderr, so we need to set output to stderr.
	// But to get control, we need to handle errors manually.
	// Instead, we'll parse manually: check if any arg starts with "-"
