			fmt.Fprintf(os.Stderr, "flag provided but not defined: %s\n", a)
			os.Exit(0)
		}
	}
	// Now positional args
	if len(args) == 0 {
		// list all checkers
		// format: each line "<name> [tags]"
		// tags in original are space separated inside brackets, but we need to preserve original order.
		// We have allCheckers in order of docList which matches original order.
		for _, ci := range allCheckers {
			fmt.Fprintf(os.Stdout, "%s [%s]\n", ci.name, strings.Join(ci.tags, " "))
		}
		os.Exit(0)
	}
	if len(args) > 1 {
		fmt.Fprint(os.Stderr, "expected 0 or 1 positional arguments\n")
		os.Exit(1)
	}
	name := args[0]
	if doc, ok := docsMap[name]; ok {
		fmt.Fprint(os.Stdout, doc)
		// docs in our map already don't have trailing newline? Original docs have no extra newline at end? Let's check: original doc ends without extra blank line? In our captured docs, they end without trailing newline? Our earlier repr shows last line without \n? Actually captured docs end with "\n"?? Let's ensure we print exactly as original. The docs we captured from original binary include no extra blank line at end? For captLocal, it ended with "(default true)\n" – no extra blank line. So we should print doc as is but ensure newline at end? Our captured docs already include newline at end? In our earlier repr, it ended with "\n" for last line. So printing as is should be fine.
		// Need to ensure we have newline at end? Original does not have double newline. So just print.
		// But our docsMap values might not have trailing newline? We'll ensure we add newline if not present? Safer to print as is and if not ends with newline, add.
		if !strings.HasSuffix(doc, "\n") {
			fmt.Fprintln(os.Stdout)
		}
		os.Exit(0)
	} else {
		fmt.Fprintf(os.Stderr, "checker with name \"%s\" not found\n", name)
		os.Exit(1)
	}
}

