func exprToString(e ast.Expr) string {
	switch v := e.(type) {
	case *ast.Ident:
		return v.Name
	case *ast.SelectorExpr:
		x := exprToString(v.X)
		if x == "" {
			return v.Sel.Name
		}
		return x + "." + v.Sel.Name
	case *ast.StarExpr:
		return "*" + exprToString(v.X)
	case *ast.ArrayType:
		elt := exprToString(v.Elt)
		if v.Len == nil {
			return "[]" + elt
		}
		return fmt.Sprintf("[%s]%s", exprToString(v.Len), elt)
	case *ast.FuncType:
		// For paramTypeCombine we only need type string for comparison, not full sig
		// For simple types like int, string, etc., Ident works
		// For more complex, we can try to handle
		return "func"
	default:
		// fallback: try to use fmt? But we need simple
		// Use token to print? For our purposes, we can attempt to handle basic types
		// If it's a basic ident, we already handled
		// For other cases, return empty to indicate unknown
		return ""
	}
}

