		"regexpSimplify [style experimental opinionated]",
		"returnAfterHttpError [diagnostic experimental]",
		"ruleguard [style experimental]",
		"singleCaseSwitch [style]",
		"sliceClear [performance experimental]",
		"sloppyLen [diagnostic]",
		"sloppyReassign [diagnostic experimental]",
		"sloppyTypeAssert [diagnostic]",
		"sortSlice [diagnostic experimental]",
		"sprintfQuotedString [diagnostic experimental]",
		"sqlQuery [diagnostic experimental]",
		"stringConcatSimplify [style experimental]",
		"stringXbytes [performance]",
		"stringsCompare [style experimental]",
		"switchTrue [style]",
		"syncMapLoadAndDelete [diagnostic experimental]",
		"timeExprSimplify [style experimental]",
		"todoCommentWithoutDetail [style opinionated experimental]",
		"tooManyResultsChecker [style opinionated experimental]",
		"truncateCmp [diagnostic experimental]",
		"typeAssertChain [style experimental]",
		"typeDefFirst [style experimental]",
		"typeSwitchVar [style]",
		"typeUnparen [style opinionated]",
		"uncheckedInlineErr [diagnostic experimental]",
		"underef [style]",
		"unlabelStmt [style experimental]",
		"unlambda [style]",
		"unnamedResult [style opinionated experimental]",
		"unnecessaryBlock [style opinionated experimental]",
		"unnecessaryDefer [diagnostic experimental]",
		"unslice [style]",
		"valSwap [style]",
		"weakCond [diagnostic experimental]",
		"whyNoLint [style experimental]",
		"wrapperFunc [style]",
		"yodaStyleExpr [style experimental]",
		"zeroByteRepeat [performance]",
	}
	allCheckers = make([]checkerInfo, 0, len(docList))
	checkerMap = make(map[string]checkerInfo)
	for _, line := range docList {
		idx := strings.Index(line, " [")
		if idx == -1 {
			continue
		}
		name := line[:idx]
		tagsStr := line[idx+2 : len(line)-1]
		tags := strings.Fields(tagsStr)
		ci := checkerInfo{name: name, tags: tags}
		allCheckers = append(allCheckers, ci)
		checkerMap[name] = ci
	}
}

func levenshtein(a, b string) int {
	la := len(a)
	lb := len(b)
	dp := make([][]int, la+1)
	for i := range dp {
		dp[i] = make([]int, lb+1)
	}
	for i := 0; i <= la; i++ {
		dp[i][0] = i
	}
	for j := 0; j <= lb; j++ {
		dp[0][j] = j
	}
	for i := 1; i <= la; i++ {
		for j := 1; j <= lb; j++ {
			cost := 0
			if a[i-1] != b[j-1] {
				cost = 1
			}
			dp[i][j] = min(dp[i-1][j]+1, min(dp[i][j-1]+1, dp[i-1][j-1]+cost))
		}
	}
	return dp[la][lb]
}
func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func suggestCommand(input string) string {
	trimmed := strings.TrimLeft(input, "-")
	candidates := []string{"check", "doc", "help", "version"}
	best := ""
	bestDist := 100
	for _, c := range candidates {
		if trimmed == c {
			return c
		}
		d1 := levenshtein(input, c)
		d2 := levenshtein(trimmed, c)
		d := d1
		if d2 < d {
			d = d2
		}
		if d <= 2 && d < bestDist {
			bestDist = d
			best = c
		}
	}
	return best
}

func handleUnknownCommand(cmd string) {
	suggest := suggestCommand(cmd)
	if suggest != "" {
		fmt.Fprintf(os.Stdout, "\"%s\" unknown command, did you mean \"%s\"?\nRun \"go-critic help\" for usage.\n\n", cmd, suggest)
	} else {
		fmt.Fprintf(os.Stdout, "\"%s\" unknown command\nRun \"go-critic help\" for usage.\n\n", cmd)
	}
	fmt.Fprintf(os.Stderr, "no such command \"%s\"\n", cmd)
	os.Exit(0)
}

func printHelp() {
	fmt.Fprint(os.Stdout, helpText)
}

func main() {
	if len(os.Args) < 2 {
		fmt.Fprint(os.Stderr, "no args provided\n")
		os.Exit(0)
	}
	cmd := os.Args[1]
	switch cmd {
	case "help":
		printHelp()
		os.Exit(0)
	case "version":
		fmt.Fprint(os.Stdout, versionText)
		os.Exit(0)
	case "doc":
		runDoc(os.Args[2:])
	case "check":
		runCheck(os.Args[2:])
	default:
		handleUnknownCommand(cmd)
	}
}

func runDoc(args []string) {
	for _, a := range args {
		if a == "-help" || a == "--help" || a == "-h" {
			fmt.Fprint(os.Stderr, "Usage of go-critic:\nflag: help requested\n")
			os.Exit(0)
		}
		if strings.HasPrefix(a, "-") {
			fmt.Fprintf(os.Stderr, "flag provided but not defined: %s\n", a)
			fmt.Fprint(os.Stderr, "Usage of go-critic:\n")
			fmt.Fprintf(os.Stderr, "flag provided but not defined: %s\n", a)
			os.Exit(0)
		}
	}
	if len(args) == 0 {
		for _, ci := range allCheckers {
			fmt.Fprintf(os.Stdout, "%s [%s]\n", ci.name, strings.Join(ci.tags, " "))
		}
		os.Exit(0)
	}
	if len(args) > 1 {
		fmt.Fprint(os.Stderr, "expected 0 or 1 positional arguments\n")
		os.Exit(1)
	}
	name := args[0]
	if doc, ok := docsMap[name]; ok {
		fmt.Fprint(os.Stdout, doc)
		if !strings.HasSuffix(doc, "\n") {
			fmt.Fprintln(os.Stdout)
		}
		os.Exit(0)
	} else {
		fmt.Fprintf(os.Stderr, "checker with name \"%s\" not found\n", name)
		os.Exit(1)
	}
}

func runCheck(args []string) {
	fs := flag.NewFlagSet("go-critic", flag.ContinueOnError)
	var flagOutput bytes.Buffer
	fs.SetOutput(&flagOutput)

	var (
		captLocalParamsOnly             bool
		commentedOutCodeMinLength       int
		elseifSkipBalanced              bool
		hugeParamSizeThreshold          int
		ifElseChainMinThreshold         int
		nestingReduceBodyWidth          int
		rangeExprCopySizeThreshold      int
		rangeExprCopySkipTestFuncs      bool
		rangeValCopySizeThreshold       int
		rangeValCopySkipTestFuncs       bool
		ruleguardDebug                  string
		ruleguardDisable                string
		ruleguardEnable                 string
		ruleguardFailOn                 string
		ruleguardFailOnError            bool
		ruleguardRules                  string
		tooManyResultsCheckerMaxResults int
		truncateCmpSkipArchDependent    bool
		underefSkipRecvDeref            bool
		unnamedResultCheckExported      bool

		checkGenerated     bool
		checkTests         bool
		concurrency        int
		cpuprofile         string
		disable            string
		enable             string
		enableAll          bool
		exitCode           int
		goVersion          string
		memprofile         string
		shorterErrLocation bool
		v                  bool
	)

	captLocalParamsOnly = true
	commentedOutCodeMinLength = 15
	elseifSkipBalanced = true
	hugeParamSizeThreshold = 80
	ifElseChainMinThreshold = 2
	nestingReduceBodyWidth = 5
	rangeExprCopySizeThreshold = 512
	rangeExprCopySkipTestFuncs = true
	rangeValCopySizeThreshold = 128
	rangeValCopySkipTestFuncs = true
	ruleguardEnable = "<all>"
	tooManyResultsCheckerMaxResults = 5
	truncateCmpSkipArchDependent = true
	underefSkipRecvDeref = true
	checkTests = true
	concurrency = runtime.GOMAXPROCS(0)
	enable = "appendAssign,argOrder,assignOp,badCall,badCond,captLocal,caseOrder,codegenComment,commentFormatting,defaultCaseOrder,deprecatedComment,dupArg,dupBranchBody,dupCase,dupSubExpr,elseif,exitAfterDefer,flagDeref,flagName,ifElseChain,mapKey,newDeref,offBy1,regexpMust,singleCaseSwitch,sloppyLen,sloppyTypeAssert,switchTrue,typeSwitchVar,underef,unlambda,unslice,valSwap,wrapperFunc"
	exitCode = 1
	shorterErrLocation = true

	fs.BoolVar(&captLocalParamsOnly, "@captLocal.paramsOnly", captLocalParamsOnly, "whether to restrict checker to params only")
	fs.IntVar(&commentedOutCodeMinLength, "@commentedOutCode.minLength", commentedOutCodeMinLength, "min length of the comment that triggers a warning")
	fs.BoolVar(&elseifSkipBalanced, "@elseif.skipBalanced", elseifSkipBalanced, "whether to skip balanced if-else pairs")
	fs.IntVar(&hugeParamSizeThreshold, "@hugeParam.sizeThreshold", hugeParamSizeThreshold, "size in bytes that makes the warning trigger")
	fs.IntVar(&ifElseChainMinThreshold, "@ifElseChain.minThreshold", ifElseChainMinThreshold, "min number of if-else blocks that makes the warning trigger")
	fs.IntVar(&nestingReduceBodyWidth, "@nestingReduce.bodyWidth", nestingReduceBodyWidth, "min number of statements inside a branch to trigger a warning")
	fs.IntVar(&rangeExprCopySizeThreshold, "@rangeExprCopy.sizeThreshold", rangeExprCopySizeThreshold, "size in bytes that makes the warning trigger")
	fs.BoolVar(&rangeExprCopySkipTestFuncs, "@rangeExprCopy.skipTestFuncs", rangeExprCopySkipTestFuncs, "whether to check test functions")
	fs.IntVar(&rangeValCopySizeThreshold, "@rangeValCopy.sizeThreshold", rangeValCopySizeThreshold, "size in bytes that makes the warning trigger")
	fs.BoolVar(&rangeValCopySkipTestFuncs, "@rangeValCopy.skipTestFuncs", rangeValCopySkipTestFuncs, "whether to check test functions")
	fs.StringVar(&ruleguardDebug, "@ruleguard.debug", ruleguardDebug, "enable debug for the specified named rules group")
	fs.StringVar(&ruleguardDisable, "@ruleguard.disable", ruleguardDisable, "comma-separated list of disabled groups or skip empty to enable everything")
	fs.StringVar(&ruleguardEnable, "@ruleguard.enable", ruleguardEnable, "comma-separated list of enabled groups or skip empty to enable everything")
	fs.StringVar(&ruleguardFailOn, "@ruleguard.failOn", ruleguardFailOn, "Determines the behavior when an error occurs while parsing ruleguard files.\nIf flag is not set, log error and skip rule files that contain an error.\nIf flag is set, the value must be a comma-separated list of error conditions.\n* 'import': rule refers to a package that cannot be loaded.\n* 'dsl':    gorule file does not comply with the ruleguard DSL.")
	fs.BoolVar(&ruleguardFailOnError, "@ruleguard.failOnError", ruleguardFailOnError, "deprecated, use failOn param; if set to true, identical to failOn='all', otherwise failOn=''")
	fs.StringVar(&ruleguardRules, "@ruleguard.rules", ruleguardRules, "comma-separated list of gorule file paths. Glob patterns such as 'rules-*.go' may be specified")
	fs.IntVar(&tooManyResultsCheckerMaxResults, "@tooManyResultsChecker.maxResults", tooManyResultsCheckerMaxResults, "maximum number of results")
	fs.BoolVar(&truncateCmpSkipArchDependent, "@truncateCmp.skipArchDependent", truncateCmpSkipArchDependent, "whether to skip int/uint/uintptr types")
	fs.BoolVar(&underefSkipRecvDeref, "@underef.skipRecvDeref", underefSkipRecvDeref, "whether to skip (*x).method() calls where x is a pointer receiver")
	fs.BoolVar(&unnamedResultCheckExported, "@unnamedResult.checkExported", unnamedResultCheckExported, "whether to check exported functions")

	fs.BoolVar(&checkGenerated, "checkGenerated", checkGenerated, "whether to check generated files")
	fs.BoolVar(&checkTests, "checkTests", checkTests, "whether to check test files")
	fs.IntVar(&concurrency, "concurrency", concurrency, "how many concurrent checkers to run (default is runtime.GOMAXPROCS(0))")
	fs.StringVar(&cpuprofile, "cpuprofile", cpuprofile, "write CPU profile to the specified file")
	fs.StringVar(&disable, "disable", disable, "comma-separated list of checkers to be disabled. Can include #tags")
	fs.StringVar(&enable, "enable", enable, "comma-separated list of enabled checkers. Can include #tags")
	fs.BoolVar(&enableAll, "enableAll", enableAll, "identical to -enable with all checkers listed. If true, -enable is ignored")
	fs.IntVar(&exitCode, "exitCode", exitCode, "exit code to be used when lint issues are found")
	fs.StringVar(&goVersion, "go", goVersion, "select the Go version to target. Leave as string for the latest")
	fs.StringVar(&memprofile, "memprofile", memprofile, "write memory profile to the specified file")
	fs.BoolVar(&shorterErrLocation, "shorterErrLocation", shorterErrLocation, "whether to replace error location prefix with $GOROOT and $GOPATH")
	fs.BoolVar(&v, "v", v, "whether to print output useful during linter debugging")

	err := fs.Parse(args)
	if err != nil {
		output := flagOutput.String()
		fmt.Fprint(os.Stderr, output)
		fmt.Fprintf(os.Stderr, "parse args: %s\n", err.Error())
		os.Exit(1)
	}

	if cpuprofile != "" {
		f, err := os.Create(cpuprofile)
		if err == nil {
			pprof.StartCPUProfile(f)
			defer pprof.StopCPUProfile()
			defer f.Close()
		}
	}

	if goVersion != "" {
		matched, _ := regexp.MatchString(`^1\.\d+$`, goVersion)
		if !matched {
			panic(fmt.Sprintf("invalid Go version format: %s", goVersion))
		}
	}

	if concurrency <= 0 {
		for {
			time.Sleep(time.Hour)
		}
	}

	var enabledList []string
	if enableAll {
		for _, ci := range allCheckers {
			enabledList = append(enabledList, ci.name)
		}
	} else {
		if enable == "" {
			enabledList = []string{}
		} else {
			parts := strings.Split(enable, ",")
			seen := make(map[string]bool)
			for _, p := range parts {
				p = strings.TrimSpace(p)
				if p == "" {
					continue
				}
				if strings.HasPrefix(p, "#") {
					tag := strings.TrimPrefix(p, "#")
					for _, ci := range allCheckers {
						for _, t := range ci.tags {
							if t == tag {
								if !seen[ci.name] {
									enabledList = append(enabledList, ci.name)
									seen[ci.name] = true
								}
							}
						}
					}
				} else {
					if _, ok := checkerMap[p]; ok {
						if !seen[p] {
							enabledList = append(enabledList, p)
							seen[p] = true
						}
					}
				}
			}
		}
	}
	if disable != "" {
		parts := strings.Split(disable, ",")
		disabledSet := make(map[string]bool)
		for _, p := range parts {
			p = strings.TrimSpace(p)
			if p == "" {
				continue
			}
			if strings.HasPrefix(p, "#") {
				tag := strings.TrimPrefix(p, "#")
				for _, ci := range allCheckers {
					for _, t := range ci.tags {
						if t == tag {
							disabledSet[ci.name] = true
						}
					}
				}
			} else {
				disabledSet[p] = true
			}
		}
		filtered := []string{}
		for _, name := range enabledList {
			if !disabledSet[name] {
				filtered = append(filtered, name)
			}
		}
		enabledList = filtered
	}

	if len(enabledList) == 0 {
		fmt.Fprint(os.Stderr, "init checkers: empty checkers set selected\n")
		os.Exit(1)
	}

	if v {
		sorted := make([]checkerInfo, len(allCheckers))
		copy(sorted, allCheckers)
		sort.Slice(sorted, func(i, j int) bool { return sorted[i].name < sorted[j].name })
		enabledSet := make(map[string]bool)
		for _, n := range enabledList {
			enabledSet[n] = true
		}
		for _, ci := range sorted {
			if enabledSet[ci.name] {
				fmt.Fprintf(os.Stderr, "\tdebug: %s is enabled\n", ci.name)
			} else {
				fmt.Fprintf(os.Stderr, "\tdebug: %s: not enabled by name or tag (-enable)\n", ci.name)
			}
		}
	}

	targets := fs.Args()
	if len(targets) == 0 {
		os.Exit(0)
	}

	hasIssues := false

	for _, target := range targets {
		if strings.HasSuffix(target, ".go") {
			info, err := os.Stat(target)
			if err != nil {
				_ = info
				continue
			}
			if info.IsDir() {
				continue
			}
			isTestFile := strings.HasSuffix(target, "_test.go")
			if isTestFile && !checkTests {
				if v {
					fmt.Fprintf(os.Stderr, "\tdebug: checking \"command-line-arguments [command-line-arguments.test]\" package (1 files)\n")
				}
				continue
			}
			if v {
				if isTestFile {
					fmt.Fprintf(os.Stderr, "\tdebug: checking \"command-line-arguments [command-line-arguments.test]\" package (1 files)\n")
				} else {
					fmt.Fprintf(os.Stderr, "\tdebug: checking \"command-line-arguments\" package (1 files)\n")
				}
			}
			fset := token.NewFileSet()
			content, err := os.ReadFile(target)
			if err != nil {
				continue
			}
			file, err := parser.ParseFile(fset, target, content, parser.ParseComments)
			if err != nil {
				continue
			}
			enabledSet := make(map[string]bool)
			for _, n := range enabledList {
				enabledSet[n] = true
			}
			if enabledSet["appendAssign"] {
				ast.Inspect(file, func(n ast.Node) bool {
					assign, ok := n.(*ast.AssignStmt)
					if !ok {
						return true
					}
					if len(assign.Lhs) != 1 || len(assign.Rhs) != 1 {
						return true
					}
					call, ok := assign.Rhs[0].(*ast.CallExpr)
					if !ok {
						return true
					}
					funIdent, ok := call.Fun.(*ast.Ident)
					if !ok || funIdent.Name != "append" {
						return true
					}
					if len(call.Args) < 1 {
						return true
					}
					shouldReport := false
					lhsStr := exprToString(assign.Lhs[0])
					argStr := exprToString(call.Args[0])
					if lhsStr != "" && argStr != "" && lhsStr != argStr {
						shouldReport = true
					}
					if shouldReport {
						pos := fset.Position(call.Pos())
						filePath := target
						fmt.Fprintf(os.Stderr, "%s:%d:%d: %s: %s\n", filePath, pos.Line, pos.Column, "appendAssign", "append result not assigned to the same slice")
						hasIssues = true
					}
					return true
				})
			}
			if enabledSet["paramTypeCombine"] {
				ast.Inspect(file, func(n ast.Node) bool {
					var params *ast.FieldList
					var pos token.Pos
					switch fn := n.(type) {
					case *ast.FuncDecl:
						if fn.Type.Params != nil {
							params = fn.Type.Params
							pos = fn.Pos()
						}
					case *ast.FuncType:
						if fn.Params != nil {
							params = fn.Params
							pos = fn.Pos()
						}
					default:
						return true
					}
					if params == nil {
						return true
					}
					list := params.List
					if len(list) < 2 {
						return true
					}
					for i := 0; i < len(list)-1; i++ {
						t1 := exprToString(list[i].Type)
						t2 := exprToString(list[i+1].Type)
						if t1 != "" && t1 == t2 {
							var origParts []string
							for _, f := range list {
								names := []string{}
								for _, n := range f.Names {
									names = append(names, n.Name)
								}
								if len(names) == 0 {
									origParts = append(origParts, t1)
								} else {
									typ := exprToString(f.Type)
									origParts = append(origParts, fmt.Sprintf("%s %s", strings.Join(names, ", "), typ))
								}
							}
							origSig := fmt.Sprintf("func(%s)", strings.Join(origParts, ", "))
							var combinedParts []string
							var currentNames []string
							var currentType string
							for _, f := range list {
								typ := exprToString(f.Type)
								if currentType == "" {
									currentType = typ
									for _, n := range f.Names {
										currentNames = append(currentNames, n.Name)
									}
									if len(f.Names) == 0 {
										currentNames = append(currentNames, "")
									}
								} else if typ == currentType {
									for _, n := range f.Names {
										currentNames = append(currentNames, n.Name)
									}
								} else {
									if len(currentNames) > 0 && currentNames[0] != "" {
										combinedParts = append(combinedParts, fmt.Sprintf("%s %s", strings.Join(currentNames, ", "), currentType))
									} else {
										combinedParts = append(combinedParts, currentType)
									}
									currentNames = []string{}
									for _, n := range f.Names {
										currentNames = append(currentNames, n.Name)
									}
									currentType = typ
								}
							}
							if len(currentNames) > 0 {
								if currentNames[0] != "" {
									combinedParts = append(combinedParts, fmt.Sprintf("%s %s", strings.Join(currentNames, ", "), currentType))
								} else {
									combinedParts = append(combinedParts, currentType)
								}
							}
							combinedSig := fmt.Sprintf("func(%s)", strings.Join(combinedParts, ", "))
							if origSig != combinedSig {
								p := fset.Position(pos)
								filePath := target
								fmt.Fprintf(os.Stderr, "%s:%d:%d: %s: %s could be replaced with %s\n", filePath, p.Line, p.Column, "paramTypeCombine", origSig, combinedSig)
								hasIssues = true
								break
							}
						}
					}
					return true
				})
			}
			if enabledSet["ifElseChain"] {
				ast.Inspect(file, func(n ast.Node) bool {
					ifStmt, ok := n.(*ast.IfStmt)
					if !ok {
						return true
					}
					count := 0
					hasElse := false
					cur := ifStmt
					for cur != nil {
						if cur.Else != nil {
							if elseIf, ok := cur.Else.(*ast.IfStmt); ok {
								count++
								cur = elseIf
							} else {
								hasElse = true
								break
							}
						} else {
							break
						}
					}
					shouldReport := false
					if count >= ifElseChainMinThreshold {
						shouldReport = true
					} else if count >= 1 && hasElse {
						shouldReport = true
					}
					if shouldReport {
						pos := fset.Position(ifStmt.Pos())
						filePath := target
						fmt.Fprintf(os.Stderr, "%s:%d:%d: %s: %s\n", filePath, pos.Line, pos.Column, "ifElseChain", "rewrite if-else to switch statement")
						hasIssues = true
					}
					return true
				})
			}
		} else {
			// package target handling via go list
			if v {
				// For package mode, we still print checking line? Original prints per package loaded, but we approximate
			}
			cmd := exec.Command("go", "list", "-f", "{{.Dir}}", target)
			out, err := cmd.Output()
			if err != nil {
				continue
			}
			dir := strings.TrimSpace(string(out))
			if dir == "" {
				continue
			}
			entries, err := os.ReadDir(dir)
			if err != nil {
				continue
			}
			var files []string
			for _, entry := range entries {
				if entry.IsDir() {
					continue
				}
				name := entry.Name()
				if !strings.HasSuffix(name, ".go") {
					continue
				}
				if strings.HasSuffix(name, "_test.go") && !checkTests {
					continue
				}
				fullPath := filepath.Join(dir, name)
				if !checkGenerated {
					content, err := os.ReadFile(fullPath)
					if err == nil {
						if bytes.Contains(content, []byte("Code generated")) && bytes.Contains(content, []byte("DO NOT EDIT")) {
							continue
						}
					}
				}
				files = append(files, fullPath)
			}
			if v {
				// Simulate checking message
				// Need to determine package name? Use target
				fmt.Fprintf(os.Stderr, "\tdebug: checking \"%s\" package (%d files)\n", target, len(files))
			}
			enabledSet := make(map[string]bool)
			for _, n := range enabledList {
				enabledSet[n] = true
			}
			for _, fullPath := range files {
				fset := token.NewFileSet()
				content, err := os.ReadFile(fullPath)
				if err != nil {
					continue
				}
				file, err := parser.ParseFile(fset, fullPath, content, parser.ParseComments)
				if err != nil {
					continue
				}
				if enabledSet["appendAssign"] {
					ast.Inspect(file, func(n ast.Node) bool {
						assign, ok := n.(*ast.AssignStmt)
						if !ok {
							return true
						}
						if len(assign.Lhs) != 1 || len(assign.Rhs) != 1 {
							return true
						}
						call, ok := assign.Rhs[0].(*ast.CallExpr)
						if !ok {
							return true
						}
						funIdent, ok := call.Fun.(*ast.Ident)
						if !ok || funIdent.Name != "append" {
							return true
						}
						if len(call.Args) < 1 {
							return true
						}
						lhsStr := exprToString(assign.Lhs[0])
						argStr := exprToString(call.Args[0])
						if lhsStr != "" && argStr != "" && lhsStr != argStr {
							pos := fset.Position(call.Pos())
							fmt.Fprintf(os.Stderr, "%s:%d:%d: %s: %s\n", fullPath, pos.Line, pos.Column, "appendAssign", "append result not assigned to the same slice")
							hasIssues = true
						}
						return true
					})
				}
				if enabledSet["ifElseChain"] {
					ast.Inspect(file, func(n ast.Node) bool {
						ifStmt, ok := n.(*ast.IfStmt)
						if !ok {
							return true
						}
						count := 0
						hasElse := false
						cur := ifStmt
						for cur != nil {
							if cur.Else != nil {
								if elseIf, ok := cur.Else.(*ast.IfStmt); ok {
									count++
									cur = elseIf
								} else {
									hasElse = true
									break
								}
							} else {
								break
							}
						}
						shouldReport := false
						if count >= ifElseChainMinThreshold {
							shouldReport = true
						} else if count >= 1 && hasElse {
							shouldReport = true
						}
						if shouldReport {
							pos := fset.Position(ifStmt.Pos())
							fmt.Fprintf(os.Stderr, "%s:%d:%d: %s: %s\n", fullPath, pos.Line, pos.Column, "ifElseChain", "rewrite if-else to switch statement")
							hasIssues = true
						}
						return true
					})
				}
			}
		}
	}

	if memprofile != "" {
		f, err := os.Create(memprofile)
		if err == nil {
			pprof.WriteHeapProfile(f)
			f.Close()
		}
	}

	if hasIssues {
		os.Exit(exitCode)
	} else {
		os.Exit(0)
	}
}

func exprToString(e ast.Expr) string {
	switch v := e.(type) {
	case *ast.Ident:
		return v.Name
	case *ast.SelectorExpr:
		x := exprToString(v.X)
		if x == "" {
			return v.Sel.Name
		}
		return x + "." + v.Sel.Name
	case *ast.StarExpr:
		return "*" + exprToString(v.X)
	case *ast.ArrayType:
		elt := exprToString(v.Elt)
		if v.Len == nil {
			return "[]" + elt
		}
		return fmt.Sprintf("[%s]%s", exprToString(v.Len), elt)
	default:
		return ""
	}
}
EOF
"}

